          float sv = util::f16_to_f32(static_cast<uint16_t>(
              ::rocjitsu::amdgpu::read_vop3_true16_src(src0, wf, lane, opsel, 0)));
          if (inst_.abs & (1u << 0))
            sv = std::fabs(sv);
          if (inst_.neg & (1u << 0))
            sv = -sv;
          return sv;
